// Hidden behaviour check: filterQuery(input, predicate) exported from the package entry, keeping
// only the parameters the predicate accepts and rebuilding the URL as withQuery does. Written
// into the scoring checkout at acceptance/hidden/ only at scoring time, after the project tests.
import assert from "node:assert/strict";
import { createJiti } from "jiti";

const u = await createJiti(import.meta.url).import("../../src/index.ts");
const failures = [];
const check = (name, fn) => {
  try {
    fn();
  } catch (error) {
    failures.push(`${name}: ${String(error && error.message).split("\n").slice(0, 6).join(" | ")}`);
  }
};
const notBar = (key) => key !== "bar";

check("filterQuery is a function exported from src/index.ts", () => {
  assert.equal(typeof u.filterQuery, "function");
});

if (typeof u.filterQuery === "function") {
  const filterQuery = u.filterQuery;
  // An input with no "?" comes back exactly as given, whatever the predicate says.
  for (const input of ["/foo", "file:///C:/x", "http://example.com", "", "/a b", "#frag", "//host/p", "/p#a=1"]) {
    check(`no query: ${JSON.stringify(input)}`, () => {
      assert.equal(filterQuery(input, () => false), input);
      assert.equal(filterQuery(input, () => true), input);
    });
  }
  // Accepting every parameter gives what withQuery(input, {}) gives (as recorded on the base).
  const identity = [
    ["/foo?", "/foo"],
    ["/foo?bar=1&baz=2", "/foo?bar=1&baz=2"],
    ["/foo?a=1&a=2&bar=3#frag", "/foo?a=1&a=2&bar=3#frag"],
    ["https://user:pw@example.com:8080/p/a?bar=1&q=%20x+y#h", "https://user:pw@example.com:8080/p/a?bar=1&q=+x+y#h"],
    ["//cdn.example.com/x?bar=1&y", "//cdn.example.com/x?bar=1&y"],
    ["file:///C:/x?bar=1&k=v", "file://C:/x?bar=1&k=v"],
    ["/p?x=1&&bar=2&", "/p?x=1&bar=2"],
    ["/p?__proto__=1&bar=2&z=3", "/p?bar=2&z=3"],
    ["http://a.com/b?x=a%26b&bar=&y=%3D", "http://a.com/b?x=a%26b&bar&y=="],
    ["/foo#h?bar=1", "/foo#h?bar=1"],
  ];
  for (const [input, expected] of identity) {
    check(`accept all: ${JSON.stringify(input)}`, () => assert.equal(filterQuery(input, () => true), expected));
