    ["?bar=1&c=3", notBar, "?c=3"],
    ["//cdn.example.com/x?bar=1&y", notBar, "//cdn.example.com/x?y"],
    ["/x?a=%2F&bar", notBar, "/x?a=%2F"],
    ["file:///C:/x?bar=1&k=v", notBar, "file://C:/x?k=v"],
    ["/p?x=1&&bar=2&", notBar, "/p?x=1"],
    ["/p?__proto__=1&bar=2&z=3", notBar, "/p?z=3"],
    ["/p?a=1&b=2&c=1", (key, value) => value === "1", "/p?a=1&c=1"],
    ["/p?a=1&a=2&b=3", (key, value) => Array.isArray(value), "/p?a=1&a=2"],
    ["/p?caf%C3%A9=1&bar=2", (key) => key === "café", "/p?caf%C3%A9=1"],
    ["http://a.com/b?x=a%26b&bar=&y=%3D", notBar, "http://a.com/b?x=a%26b&y=="],
    ["/p?b=2&a=1", (key) => key === "a", "/p?a=1"],
  ];
  for (const [input, predicate, expected] of filtered) {
    check(`filter: ${JSON.stringify(input)} with ${predicate.toString()}`, () =>
      assert.equal(filterQuery(input, predicate), expected),
    );
  }
  check("the predicate sees each decoded key once, in order, with getQuery's value", () => {
    const calls = [];
    filterQuery("/p?b=2&a=1&a=3&caf%C3%A9=x&e", (...args) => {
      calls.push([args[0], args[1]]);
      return true;
    });
    assert.deepEqual(calls, [["b", "2"], ["a", ["1", "3"]], ["café", "x"], ["e", ""]]);
